public static CanonicalSessionState pauseAfterRestart(CanonicalSessionState state) {
    if (state.activeRun().isEmpty() || state.activeRun().orElseThrow().status() == PAUSED) return state;
    CanonicalSessionState.Run run = state.activeRun().orElseThrow();
    if (run.status() == CanonicalSessionState.RunStatus.TERMINAL) return state;
    var turns = new ArrayList<>(run.turns());
    if (!turns.isEmpty() && turns.getLast().status() != CanonicalSessionState.TurnStatus.TERMINAL) {
        turns.set(turns.size() - 1, pause(turns.getLast()));
    }
    CanonicalSessionState.RunPauseReason reason = run.status() == CanonicalSessionState.RunStatus.CANCELLING
            ? CanonicalSessionState.RunPauseReason.CANCELLATION_PENDING : HOST_RESTART;
    CanonicalSessionState.Run paused = new CanonicalSessionState.Run(
            run.id(), run.sessionId(), PAUSED, Optional.empty(), Optional.of(reason),
            increment(run.revision()), turns, run.startedAt(), Optional.empty());
    return new CanonicalSessionState(
            state.sessionId(), state.status(), increment(state.revision()),
            Optional.of(paused), state.completedRuns(), pauseCompactions(state.compactions()));
}

